@@ -0,0 +1,24 @@
+import { slugify } from "../lib/text.js";
+import { formatDate } from "../lib/date.js";
+
+function eventTitle(event) {
+  const title = typeof event?.title === "string" ? event.title.trim() : "";
+  if (!title) {
+    throw new TypeError("Event title is required");
+  }
+  return title;
+}
+
+function eventDateLabel(event) {
+  const startsAt = event?.startsAt;
+  if (startsAt === null || startsAt === undefined || startsAt === "") {
+    throw new TypeError("Invalid event date");
+  }
+  return formatDate(startsAt);
+}
+
+export function createEventCard(event) {
+  const title = eventTitle(event);
+  const dateLabel = eventDateLabel(event);
+  return { id: slugify(title), title, dateLabel };
+}

