@@ -0,0 +1,12 @@
+import { createEventCard, eventStartTime } from "./event-card.js";
+
+export function sortChronologically(events, build) {
+  return events
+    .map((event, index) => ({ value: build(event), time: eventStartTime(event), index }))
+    .sort((a, b) => a.time - b.time || a.index - b.index)
+    .map((entry) => entry.value);
+}
+
+export function buildAgenda(events) {
+  return sortChronologically(events, createEventCard);
+}
